```javascript
/**
 * Parses a URL query string into an object.
 *
 * Features:
 * - Handles leading "?" and full URLs
 * - Decodes URI components (including "+" as space)
 * - Repeated keys become arrays: "a=1&a=2" → { a: ["1", "2"] }
 * - Bracket array syntax: "a[]=1&a[]=2" → { a: ["1", "2"] }
 * - Nested objects: "user[name]=Bob" → { user: { name: "Bob" } }
 * - Keys without values: "flag" → { flag: "" }
 *
 * @param {string} queryString
 * @returns {Object}
 */
function parseQueryString(queryString) {
  const result = Object.create(null); // avoids prototype pollution

  if (typeof queryString !== 'string' || !queryString) return {};

  // Strip everything up to and including "?", and drop any hash fragment
  let qs = queryString;
  const qIndex = qs.indexOf('?');
  if (qIndex !== -1) qs = qs.slice(qIndex + 1);
  const hashIndex = qs.indexOf('#');
  if (hashIndex !== -1) qs = qs.slice(0, hashIndex);

  const decode = (str) => {
    try {
      return decodeURIComponent(str.replace(/\+/g, ' '));
    } catch {
      return str; // malformed encoding: return raw value
    }
  };

  const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

  for (const pair of qs.split('&')) {
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    const rawKey = eqIndex === -1 ? pair : pair.slice(0, eqIndex);
    const rawValue = eqIndex === -1 ? '' : pair.slice(eqIndex + 1);

    const key = decode(rawKey);
    const value = decode(rawValue);

    // Split "user[address][city]" into ["user", "address", "city"]
    const match = key.match(/^([^[\]]+)((?:\[[^[\]]*\])*)$/);
    const path = match
      ? [match[1], ...(match[2].match(/\[([^[\]]*)\]/g) || []).map((s) => s.slice(1, -1))]
      : [key];

    if (path.some((segment) => UNSAFE_KEYS.has(segment))) continue;

    assign(result, path, value);
  }

  return { ...result };
}

function assign(target, path, value) {
  let current = target;

  for (let i = 0; i < path.length; i++) {
    const segment = path[i];
    const isLast = i === path.length - 1;

    if (isLast) {
      if (segment === '') {
        // "a[]=1" → push onto array
        if (Array.isArray(current)) current.push(value);
      } else if (segment in current) {
        // Repeated key → convert to array
        const existing = current[segment];
        current[segment] = Array.isArray(existing)
          ? [...existing, value]
          : [existing, value];
      } else {
        current[segment] = value;
      }
      return;
    }

    const nextIsArray = path[i + 1] === '';

    if (segment === '') {
      // Array of objects isn't well-defined; append a new container
      const container = nextIsArray ? [] : Object.create(null);
      current.push(container);
      current = container;
      continue;
    }

    if (
      !(segment in current) ||
      typeof current[segment] !== 'object' ||
      current[segment] === null
    ) {
      current[segment] = nextIsArray ? [] : Object.create(null);
    }

    current = current[segment];
  }
