Here's a robust query string parser that handles common real-world cases:

```javascript
function parseQueryString(query) {
  const result = {};

  if (typeof query !== 'string') return result;

  // Strip everything up to and including "?" and any hash fragment
  const qIndex = query.indexOf('?');
  if (qIndex !== -1) query = query.slice(qIndex + 1);
  const hashIndex = query.indexOf('#');
  if (hashIndex !== -1) query = query.slice(0, hashIndex);

  if (!query) return result;

  const decode = (str) => {
    const s = str.replace(/\+/g, ' ');
    try {
      return decodeURIComponent(s);
    } catch {
      return s; // malformed encoding: return as-is
    }
  };

  for (const pair of query.split('&')) {
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    const rawKey = eqIndex === -1 ? pair : pair.slice(0, eqIndex);
    const rawValue = eqIndex === -1 ? '' : pair.slice(eqIndex + 1);

    let key = decode(rawKey);
    const value = decode(rawValue);

    // Guard against prototype pollution
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;

    // Support array syntax: tags[]=a&tags[]=b
    const isArrayKey = key.endsWith('[]');
    if (isArrayKey) key = key.slice(0, -2);

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      // Repeated key: convert to array
      result[key] = [].concat(result[key], value);
    } else {
      result[key] = isArrayKey ? [value] : value;
    }
  }

  return result;
}
```

