## 4. Iterative approach (avoids recursion depth limits)

```javascript
function flatten(arr) {
  const stack = [...arr];
  const result = [];
  while (stack.length) {
    const item = stack.pop();
    if (Array.isArray(item)) {
      stack.push(...item);
    } else {
      result.unshift(item); // unshift preserves order
    }
  }
  return result;
}
