```js
/**
 * Parse a query string into an object.
 *
 * @param {string} queryString  e.g. "?name=John&role=admin&role=dev"
 * @returns {Record<string, string | string[]>}
 */
function parseQueryString(queryString) {
  const result = {};
  if (typeof queryString !== 'string') return result;

  // Strip a leading "?" and any "#fragment"
  const qs = queryString.trim().replace(/^\?/, '').split('#')[0];
  if (!qs) return result;

  // Decode %XX sequences; "+" means space. Malformed input is left as-is.
  const decode = (s) => {
    try {
      return decodeURIComponent(s.replace(/\+/g, ' '));
    } catch {
      return s;
    }
  };

  // defineProperty avoids the "__proto__" setter (prototype pollution)
  const set = (key, value) =>
    Object.defineProperty(result, key, {
      value, writable: true, enumerable: true, configurable: true,
    });

  for (const pair of qs.split('&')) {
    if (!pair) continue;

    const eq = pair.indexOf('=');
    const key = decode(eq === -1 ? pair : pair.slice(0, eq));
    const value = eq === -1 ? '' : decode(pair.slice(eq + 1));
    if (!key) continue;

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      // Repeated key -> collect into an array
      const prev = result[key];
      set(key, Array.isArray(prev) ? [...prev, value] : [prev, value]);
    } else {
      set(key, value);
    }
  }

  return result;
}
```

