```js
/**
 * Parse a query string into a plain object.
 *
 * @param {string} queryString  e.g. "?name=John%20Doe&tags=a&tags=b"
 * @param {object} [options]
 * @param {boolean} [options.decode=true]        Decode %XX and '+' (space)
 * @param {boolean} [options.repeatsAsArray=true] Repeated keys become arrays
 * @param {boolean} [options.nullProto=true]      Use Object.create(null) (safe from prototype pollution)
 * @returns {Object}
 */
function parseQueryString(queryString, options = {}) {
  const { decode = true, repeatsAsArray = true, nullProto = true } = options;

  if (typeof queryString !== 'string') {
    throw new TypeError('parseQueryString: expected a string');
  }

  // Drop any hash fragment, then the leading "?"
  let qs = queryString.trim();
  const hash = qs.indexOf('#');
  if (hash !== -1) qs = qs.slice(0, hash);
  if (qs.startsWith('?')) qs = qs.slice(1);

  const result = nullProto ? Object.create(null) : {};

  if (qs === '') return result;

  const decodePart = (str) => {
    if (!decode) return str;
    try {
      return decodeURIComponent(str.replace(/\+/g, ' '));
    } catch {
      return str; // malformed %-encoding: keep the raw text
    }
  };

  for (const pair of qs.split('&')) {
    if (pair === '') continue;

    // Split on the FIRST "=" so values may contain "="
    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);

    const key = decodePart(rawKey);
    const value = decodePart(rawValue);

    if (repeatsAsArray && key in result) {
      if (Array.isArray(result[key])) result[key].push(value);
      else result[key] = [result[key], value];
    } else {
      result[key] = value;
    }
  }

  return result;
}
```

