## Advanced Version

Handles repeated keys (as arrays), nested keys (`a[b]=c`), and array syntax (`a[]=1`):

```javascript
function parseQueryString(queryString, options = {}) {
  const { repeated = 'last', nested = false } = options;
  const result = {};

  const query = queryString.replace(/^[?#]/, '');
  if (!query) return result;

  const setValue = (obj, path, value) => {
    let current = obj;

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i];
      if (current[key] === undefined || typeof current[key] !== 'object') {
        current[key] = {};
      }
      current = current[key];
    }

    const lastKey = path[path.length - 1];

    if (current[lastKey] === undefined) {
      current[lastKey] = value;
    } else if (Array.isArray(current[lastKey])) {
      current[lastKey].push(value);
    } else if (repeated === 'array') {
      current[lastKey] = [current[lastKey], value];
    } else if (repeated === 'first') {
      // keep existing value
    } else {
      current[lastKey] = value; // 'last' (default)
    }
  };

  for (const pair of query.split('&')) {
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    const rawKey = eqIndex === -1 ? pair : pair.slice(0, eqIndex);
    const rawValue = eqIndex === -1 ? '' : pair.slice(eqIndex + 1);

    const key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const value = decodeURIComponent(rawValue.replace(/\+/g, ' '));

    if (!nested) {
      setValue(result, [key], value);
    } else {
      // "a[b][c]=1" -> ['a', 'b', 'c'];  "a[]=1" -> ['a', '']
      const path = key
        .replace(/\[([^\]]*)\]/g, '.$1')
        .split('.')
        .filter((p) => p !== '');

      if (path.length === 0) continue;

      // Handle trailing empty bracket: a[]=1&a[]=2
      if (key.endsWith('[]')) {
        const base = path.slice(0, -1);
        if (!result[base[0]] || !Array.isArray(result[base[0]])) {
          result[base[0]] = [];
        }
        result[base[0]].push(value);
      } else {
        setValue(result, path, value);
      }
    }
  }

  return result;
}
```

**Usage:**

```javascript
parseQueryString('tag=a&tag=b&tag=c', { repeated: 'array' });
// { tag: ['a', 'b', 'c'] }

parseQueryString('tag=a&tag=b'); // default 'last'
// { tag: 'b' }

parseQueryString('user[name]=John&user[age]=30', { nested: true });
// { user: { name: 'John', age: '30' } }

parseQueryString('ids[]=1&ids[]=2', { nested: true });
// { ids: ['1', '2'] }
```

