 * Parse a query string into an object.
 *
 * @param {string} queryString - e.g. "?name=John&age=30" or "name=John&age=30"
 * @param {Object} [options]
 * @param {boolean} [options.arrayForRepeats=false] - Collect repeated keys into an array.
 * @returns {Object}
 */
function parseQueryString(queryString, options = {}) {
  const { arrayForRepeats = false } = options;
  const result = {};

  if (typeof queryString !== 'string' || queryString === '') {
    return result;
