## Full-featured implementation

```js
/**
 * Parse a query string into a plain object.
 *
 * - Accepts a leading "?" or "#" (or neither)
 * - Decodes percent-encoding and "+" as space
 * - Repeated keys collapse into an array
 * - Keys with no "=" get an empty-string value
 * - Malformed percent-encoding falls back to the raw text
 * - Uses a null prototype so "__proto__" can't pollute Object.prototype
 *
 * @param {string} queryString
 * @returns {Record<string, string | string[]>}
 */
function parseQueryString(queryString) {
  const result = Object.create(null);

  if (typeof queryString !== 'string') return result;

  const qs = queryString.replace(/^[?#]/, '');
  if (!qs) return result;

  for (const pair of qs.split('&')) {
    if (!pair) continue;

    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);

    const key = decodeComponent(rawKey);
    if (!key) continue;

    const value = decodeComponent(rawValue);

    if (key in result) {
      // Duplicate key: promote to an array.
      if (Array.isArray(result[key])) result[key].push(value);
      else result[key] = [result[key], value];
    } else {
      result[key] = value;
    }
  }

  return result;
}

function decodeComponent(str) {
  try {
    return decodeURIComponent(str.replace(/\+/g, ' '));
  } catch {
    return str; // e.g. "%E0%A4%A" — keep the raw value instead of throwing
  }
