## Optional: nested keys (`a[b][c]=1`)

Add this if you want bracket syntax to build nested objects:

```js
function parseQueryStringNested(queryString) {
  const result = Object.create(null);
  if (typeof queryString !== 'string') return result;

  const qs = queryString.replace(/^[?#]/, '');

  for (const pair of qs.split('&')) {
    if (!pair) continue;

    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);

    const path = parseKey(decodeComponent(rawKey));
    if (!path.length) continue;

    const value = decodeComponent(rawValue);
    let node = result;

    for (let i = 0; i < path.length - 1; i++) {
      const k = path[i];
      if (typeof node[k] !== 'object' || node[k] === null) node[k] = Object.create(null);
      node = node[k];
    }

    const last = path[path.length - 1];
    if (last in node) {
      if (Array.isArray(node[last])) node[last].push(value);
      else node[last] = [node[last], value];
    } else {
      node[last] = value;
    }
  }

  return result;
}

// "user[name][first]=Ada" -> ['user', 'name', 'first']
function parseKey(key) {
  const parts = [];
  const re = /([^[\]]+)|\[([^\]]*)\]/g;
  let m;
  while ((m = re.exec(key)) !== null) {
    parts.push(m[1] !== undefined ? m[1] : m[2]);
  }
  return parts;
}
```

