### Things to watch out for

- **Prototype pollution:** using `Object.create(null)` (or a `Map`) means a `__proto__[x]=y` parameter can't modify `Object.prototype`. If you prefer a normal object, use `Object.defineProperty` when assigning.
- **Type coercion:** everything stays a string. Convert explicitly (`Number(params.page)`, `params.active === 'true'`).
- **Empty values vs. missing keys:** `?a=` gives `''`, while a missing `a` gives `undefined` — check with `in` or `Object.hasOwn` rather than truthiness.
- **Legacy `;` separators:** some old servers used `;` instead of `&`; split on `/[&;]/` if you need to support them.

## A robust query string parser

```js
/**
 * Parse a query string into an object.
 *
 * @param {string} queryString  e.g. "?name=John&age=30"
 * @returns {Record<string, string | string[]>}
 */
function parseQueryString(queryString) {
  // Null prototype => no inherited props, and "__proto__" can't pollute Object.prototype
  const result = Object.create(null);

  if (typeof queryString !== "string" || queryString.length === 0) return result;

  // 1. Drop any hash fragment, strip a leading "?"
  const query = queryString.replace(/#.*$/, "").replace(/^\?/, "");
  if (!query) return result;

  // 2. Split into key/value pairs
  for (const pair of query.split("&")) {
    if (!pair) continue;

    // Only the FIRST "=" separates key from value, so values may contain "="
    const eq = pair.indexOf("=");
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? "" : pair.slice(eq + 1);

    const key = decodeComponent(rawKey);
    const value = decodeComponent(rawValue);
    if (!key) continue;

    // 3. Repeated keys collect into an array
    if (key in result) {
      if (Array.isArray(result[key])) result[key].push(value);
      else result[key] = [result[key], value];
    } else {
      result[key] = value;
    }
  }

  return result;
}

/** Decode percent-encoding and "+" (space), tolerating malformed input. */
function decodeComponent(str) {
  try {
    return decodeURIComponent(str.replace(/\+/g, " "));
  } catch {
    return str; // e.g. "%E0%A4%A" — keep the raw text
  }
}
```

### Examples

```js
parseQueryString("?name=John&age=30");
// { name: 'John', age: '30' }

parseQueryString("tag=a&tag=b&tag=c");
// { tag: ['a', 'b', 'c'] }

parseQueryString("q=hello%20world&note=a%2Bb");
// { q: 'hello world', note: 'a+b' }

parseQueryString("url=https://x.com/?a=1");
// { url: 'https://x.com/?a=1' }   // only the first "=" splits

parseQueryString("flag&empty=");
// { flag: '', empty: '' }

parseQueryString("?name=John#section");
// { name: 'John' }                // fragment removed
```

### Notes

- **Prototype pollution:** `Object.create(null)` means `__proto__`, `constructor`, etc. become plain own properties instead of touching `Object.prototype`. If you'd rather have a normal object, use `{}` and skip keys like `__proto__`.
- **Null-prototype caveat:** the result has no `hasOwnProperty`/`toString`. Use `Object.hasOwn(obj, key)` or `Object.keys(obj)`.
- **Types:** everything is a string. If you want numbers/booleans, add a coercion step (e.g. `v === "true" ? true : v === "false" ? false : /^\d+$/.test(v) ? Number(v) : v`).

