  for (const pair of qs.split('&')) {
    if (!pair) continue;

    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);

    const key = safeDecode(rawKey);
    const value = safeDecode(rawValue);

    if (key in params) {
      params[key] = Array.isArray(params[key])
        ? [...params[key], value]
        : [params[key], value];
    } else {
      params[key] = value;
    }
  }

  return params;
}
```

### Behavior notes
- Strips a leading `?` or `#`.
- `+` is decoded as a space; `%XX` escapes are decoded via `decodeURIComponent`.
- A key with no `=` gets an empty string value (`?flag` → `flag: ''`).
- Repeated keys are collected into an array (`?tag=a&tag=b` → `tag: ['a', 'b']`).
- Values are always strings; convert with `Number()`, `Boolean()`, etc. as needed.

```js
const q = parseQueryString('search=hello%20world&page=2&sort=asc&sort=desc');
// { search: 'hello world', page: '2', sort: ['asc', 'desc'] }
```

## `parseQueryString`

```javascript
/**
 * Parses a query string into an object.
 *
 * - Handles a leading "?" (e.g. "?a=1&b=2")
 * - Decodes URI components and "+" as space
 * - Collects repeated keys into arrays
 * - Ignores malformed percent-encoding instead of throwing
 *
 * @param {string} queryString
 * @returns {Record<string, string | string[]>}
 */
function parseQueryString(queryString) {
  const result = {};

  if (typeof queryString !== 'string' || queryString.length === 0) {
    return result;
  }

  // Remove leading "?" and any fragment ("#...")
  let qs = queryString.replace(/^[?#]/, '').split('#')[0];
  if (!qs) return result;

  const safeDecode = (str) => {
    try {
      return decodeURIComponent(str.replace(/\+/g, ' '));
    } catch {
      return str; // malformed %-encoding: keep raw value
    }
  };

  for (const pair of qs.split('&')) {
    if (!pair) continue;

    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);

    const key = safeDecode(rawKey);
    const value = safeDecode(rawValue);

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      // Duplicate key -> store as array
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}
```

### Examples

```javascript
parseQueryString('?name=John&age=30');
// { name: 'John', age: '30' }

parseQueryString('search=hello+world&tag=a&tag=b');
// { search: 'hello world', tag: ['a', 'b'] }

parseQueryString('q=100%25%20off&redirect');
// { q: '100% off', redirect: '' }   (no "=" means empty value)

parseQueryString('name=Jos%C3%A9');
// { name: 'José' }

parseQueryString('');            // {}
parseQueryString('a=1#section'); // { a: '1' }  (fragment stripped)
```

### Notes

- **Prototype safety:** keys like `__proto__` are stored as plain own properties because the duplicate check uses `hasOwnProperty` rather than the `in` operator.
- **Modern alternative:** if you don't need array handling for duplicate keys, the built-in `URLSearchParams` is simpler:

```javascript
const params = new URLSearchParams('?name=John&age=30');
const obj = Object.fromEntries(params); // { name: 'John', age: '30' }
```

