```

### Examples

```javascript
parseQueryString('?name=John&age=30');
// { name: 'John', age: '30' }

parseQueryString('search=web+dev&lang=js');
// { search: 'web dev', lang: 'js' }

parseQueryString('tag=a&tag=b&tag=c');
